package com.vianerapps.liya;

import android.graphics.Bitmap;
import android.graphics.BitmapFactory;
import android.util.Base64;

final class LiyaHairFrames {
    private static final String[] DATA = {
        "", "", "", "", ""
    };

    static Bitmap[] load() {
        Bitmap[] frames = new Bitmap[DATA.length];
        for (int i = 0; i < DATA.length; i++) {
            byte[] bytes = Base64.decode(DATA[i], Base64.DEFAULT);
            frames[i] = BitmapFactory.decodeByteArray(bytes, 0, bytes.length);
        }
        return frames;
    }

    private LiyaHairFrames() { }
}
